"""Render `latest-versions.json`, the newest schema version of each query kind, for the frontend.

A renderer in the projection registry (`tools/hogli-commands/hogli_commands/projections.py`). Run
`hogli build:projections --only schema-latest-versions` after adding a schema migration.
"""

import json

from posthog.schema_migrations import LATEST_VERSIONS, _discover_migrations

OUTPUT = "frontend/src/queries/schema/latest-versions.json"


def render() -> dict[str, str]:
    _discover_migrations()
    with_comment = {
        "//": "THIS FILE IS AUTOGENERATED. DO NOT EDIT MANUALLY. To update: hogli build:projections",
        **LATEST_VERSIONS,
    }
    return {OUTPUT: json.dumps(with_comment, sort_keys=True)}
